/** @typedef {import("../types.mjs").Finding} Finding */
/** @typedef {import("../types.mjs").RuleContext} RuleContext */
import { PROVIDER_QUALIFIED } from "../lib/patterns.mjs";

export const id = "PC-01";
export const title = "Every model id in config/routing.json is provider-qualified (provider/id)";
export const closes = ["REQ-PRV-03"];

/** @param {RuleContext} ctx @returns {Finding[]} */
export function run(ctx) {
  // config/routing.json and config/models.json are generated by the installer and git-ignored.
  // Before the first install only the tracked *.default.json templates are on disk, and the rule
  // has to check those instead — otherwise `pi-check` on a fresh clone reports the repo's own
  // shipped defaults as broken, which is exactly backwards.
  const REL = ctx.exists("config/routing.json") ? "config/routing.json" : "config/routing.default.json";
  if (!ctx.exists(REL)) return [];

  /** @type {Finding[]} */
  const findings = [];
  let routing;
  try {
    routing = ctx.readJSON(REL);
  } catch (err) {
    return [{ rule: id, file: REL, message: String(err.message ?? err) }];
  }

  const tiers = routing && typeof routing === "object" ? routing.tiers : undefined;
  if (!tiers || typeof tiers !== "object") return findings;

  const fileLines = ctx.lines(REL);
  for (const [tierName, tier] of Object.entries(tiers)) {
    const model = tier && typeof tier === "object" ? tier.model : undefined;
    if (typeof model !== "string" || model.length === 0) continue; // PC-02's job: tier must resolve
    if (PROVIDER_QUALIFIED.test(model)) continue;

    const line = fileLines.find((l) => l.text.includes(`"${model}"`))?.line;
    findings.push({
      rule: id,
      file: REL,
      line,
      message: `tier "${tierName}" model "${model}" is not provider-qualified — write "<provider>/${model}"`,
    });
  }
  return findings;
}
